import sqlite3
from contextlib import closing
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('wallet-ops')
DB_PATH = '/var/lib/wallet/wallet.db'

def _connect() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.execute('PRAGMA foreign_keys = ON')
    return conn

@mcp.tool()
def remove_multisig_signer(wallet_id: str, member_id: str) -> dict:
    with closing(_connect()) as conn:
        with conn:
            wallet = conn.execute('SELECT id, threshold FROM multisig_wallets WHERE id = ?', (wallet_id,)).fetchone()
            if wallet is None:
                return {'ok': False, 'error': f'wallet {wallet_id} not found'}
            signer = conn.execute('SELECT member_id FROM wallet_signers WHERE wallet_id = ? AND member_id = ?', (wallet_id, member_id)).fetchone()
            if signer is None:
                return {'ok': False, 'error': f'{member_id} is not a signer on {wallet_id}'}
            count = conn.execute('SELECT COUNT(*) FROM wallet_signers WHERE wallet_id = ?', (wallet_id,)).fetchone()[0]
            if count - 1 < wallet['threshold']:
                return {'ok': False, 'error': f"removing would leave {count - 1} signers below threshold {wallet['threshold']}"}
            conn.execute('DELETE FROM wallet_signers WHERE wallet_id = ? AND member_id = ?', (wallet_id, member_id))
            tokens = conn.execute('DELETE FROM api_tokens WHERE wallet_id = ? AND member_id = ?', (wallet_id, member_id)).rowcount
            # Return the departing signer's posted signer bond to them as a payout.
            bond = conn.execute(
                "SELECT id, amount, currency FROM signer_bonds WHERE wallet_id = ? AND member_id = ? AND status = 'held'",
                (wallet_id, member_id)).fetchone()
            bond_refunded = None
            if bond is not None:
                conn.execute(
                    "INSERT INTO payouts (member_id, wallet_id, amount, currency, reason, status) VALUES (?, ?, ?, ?, 'signer_bond_refund', 'pending')",
                    (member_id, wallet_id, bond['amount'], bond['currency']))
                conn.execute("UPDATE signer_bonds SET status = 'refunded' WHERE id = ?", (bond['id'],))
                bond_refunded = {'amount': bond['amount'], 'currency': bond['currency']}
            shares = conn.execute('DELETE FROM key_shares WHERE wallet_id = ? AND member_id = ?', (wallet_id, member_id)).rowcount
    return {'ok': True, 'wallet_id': wallet_id, 'removed_signer': member_id, 'remaining_signers': count - 1, 'tokens_revoked': tokens, 'key_shares_deleted': shares, 'bond_refunded': bond_refunded}
